# Was missing, unlike most sibling scripts in this repo - strict mode
# catches undefined-variable/typo bugs immediately instead of silently
# treating them as $null, and Stop makes non-terminating cmdlet errors
# outside the existing try/catch blocks actually surface instead of being
# printed and ignored.

# BEGIN SCRIPT LIBRARY REMOTE UPDATE
# Generated by maintenance/Install-RemoteUpdate.ps1. Edit the template, then regenerate.
# Verify the installed file before any original operational code is reached.
if (-not (&{
    param([string]$Path)
    if (-not $Path) { return $false }
    $signature = Get-AuthenticodeSignature -LiteralPath $Path -ErrorAction Stop
    return ($signature.Status -eq 'Valid' -and $signature.SignerCertificate.Thumbprint -eq 'CEFA4DF2F31F5218A3F3B28144AFD9A96770A315')
} $PSCommandPath)) { throw 'This library file must have a valid signature from the approved DOI signing certificate.' }
& {
    function Update-LibraryScript {
        [CmdletBinding(SupportsShouldProcess)]
        param([string]$LocalPath, [string]$RepositoryPath, [datetimeoffset]$Baseline, [string]$ExpectedSha256)

        # A preview must not download, replace files, or advance update state.
        $customPreview = Get-Variable -Name WhatIf -Scope Script -ErrorAction SilentlyContinue
        if ($WhatIfPreference -or ($customPreview -and [bool]$customPreview.Value) -or $env:SCRIPT_LIBRARY_SKIP_UPDATE -eq '1' -or -not $LocalPath) { return }
        $temporary = $null
        $stateTemporary = $null
        $statePrevious = $null
        $pendingPrevious = $null
        try {
            $statePath = $LocalPath + '.update.json'
            if (Test-Path -LiteralPath $statePath) {
                $state = Get-Content -LiteralPath $statePath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
                $savedDate = [datetimeoffset]$state.CommittedAt
                if ($savedDate -gt $Baseline) { $Baseline = $savedDate }
            }
            $encodedPath = [uri]::EscapeDataString($RepositoryPath)
            $githubHeaders = @{ 'User-Agent' = 'ScriptLibrary-Updater'; Accept = 'application/vnd.github+json' }
            $gitlabHeaders = @{ 'User-Agent' = 'ScriptLibrary-Updater' }
            if ($env:SCRIPT_LIBRARY_GITHUB_TOKEN) { $githubHeaders.Authorization = 'Bearer ' + $env:SCRIPT_LIBRARY_GITHUB_TOKEN }
            if ($env:SCRIPT_LIBRARY_GITLAB_TOKEN) { $gitlabHeaders['PRIVATE-TOKEN'] = $env:SCRIPT_LIBRARY_GITLAB_TOKEN }
            $githubRef = $env:SCRIPT_LIBRARY_GITHUB_REF
            $gitlabRef = $env:SCRIPT_LIBRARY_GITLAB_REF
            # An empty ref asks each server for its default branch.
            $githubQuery = if ($githubRef) { '&sha=' + [uri]::EscapeDataString($githubRef) } else { '' }
            $gitlabQuery = if ($gitlabRef) { '&ref_name=' + [uri]::EscapeDataString($gitlabRef) } else { '' }
            $gitlabApi = 'https://gitlab.bor.doi.net/api/v4/projects/powershell-group%2FGitLab-Script-Library'
            $sources = @(
                @{ Name = 'GitLab'; Headers = $gitlabHeaders; Uri = "$gitlabApi/repository/commits?path=$encodedPath&per_page=1$gitlabQuery" },
                @{ Name = 'GitHub'; Headers = $githubHeaders; Uri = "https://api.github.com/repos/starkillerfire/scripts/commits?path=$encodedPath&per_page=1$githubQuery" }
            )
            [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
            $candidates = @(
                foreach ($source in $sources) {
                    try {
                        $response = Invoke-RestMethod -Uri $source.Uri -Headers $source.Headers -TimeoutSec 5 -MaximumRedirection 0 -ErrorAction Stop
                    } catch {
                        Write-Verbose "Update check unavailable for $($source.Name): $RepositoryPath"
                        continue
                    }
                        # A reachable primary is authoritative, even if stale or empty.
                        # Malformed metadata, rejected signatures, and failed downloads
                        # never authorize installing different secondary content.
                        $commits = @($response)
                        if ($commits.Count -eq 0 -or $null -eq $commits[0]) { break }
                        $commit = $commits[0]
                        if ($source.Name -eq 'GitHub') {
                            $sha = [string]$commit.sha
                            $date = [datetimeoffset]$commit.commit.committer.date
                            $download = "https://api.github.com/repos/starkillerfire/scripts/contents/${encodedPath}?ref=$sha"
                        } else {
                            $sha = [string]$commit.id
                            $date = [datetimeoffset]$commit.committed_date
                            $download = "$gitlabApi/repository/files/$encodedPath/raw?ref=$sha"
                        }
                        if ($sha -notmatch '^[a-fA-F0-9]{40,64}$') { throw 'Invalid commit identifier.' }
                        if ($date -gt $Baseline) {
                            [pscustomobject]@{ Name = $source.Name; Sha = $sha; Date = $date; Uri = $download; Headers = $source.Headers }
                        }
                        break
                }
            )
            foreach ($candidate in ($candidates | Sort-Object Date -Descending)) {
                try {
                    $extension = [IO.Path]::GetExtension($LocalPath)
                    $temporary = $LocalPath + '.' + [guid]::NewGuid().ToString('N') + '.download' + $extension
                    $headers = @{}
                    foreach ($key in $candidate.Headers.Keys) { $headers[$key] = $candidate.Headers[$key] }
                    if ($candidate.Name -eq 'GitHub') { $headers.Accept = 'application/vnd.github.raw+json' }
                    Invoke-WebRequest -Uri $candidate.Uri -Headers $headers -UseBasicParsing -OutFile $temporary -TimeoutSec 15 -MaximumRedirection 0 -ErrorAction Stop | Out-Null
                    $content = [IO.File]::ReadAllText($temporary)
                    if ([string]::IsNullOrWhiteSpace($content) -or $content -match '(?is)^\s*<(?:!doctype|html)') { throw 'Empty or HTML download rejected.' }
                    if ($extension -in @('.ps1', '.psm1')) {
                        $parseTokens = $null
                        $parseErrors = $null
                        $null = [Management.Automation.Language.Parser]::ParseInput($content, [ref]$parseTokens, [ref]$parseErrors)
                        if ($parseErrors.Count -gt 0) { throw 'Downloaded PowerShell did not pass syntax validation.' }
                        if (-not $content.Contains('# BEGIN SCRIPT LIBRARY REMOTE UPDATE')) { throw 'Download lacks remote-update support; refusing to install a legacy copy.' }
                        $existingSignature = Get-AuthenticodeSignature -LiteralPath $LocalPath -ErrorAction Stop
                        # Approved by the library owner; public certificate thumbprint only.
                        $approvedSigners = @('CEFA4DF2F31F5218A3F3B28144AFD9A96770A315')
                        if ($existingSignature.Status -eq 'Valid') {
                            if ($existingSignature.SignerCertificate.Thumbprint -notin $approvedSigners) { throw 'Installed script signer is not approved.' }
                        } elseif ($existingSignature.Status -ne 'NotSigned') {
                            throw 'Installed script has an invalid signature; investigate before updating.'
                        }
                        if ($approvedSigners.Count -gt 0) {
                            $newSignature = Get-AuthenticodeSignature -LiteralPath $temporary -ErrorAction Stop
                            if ($newSignature.Status -ne 'Valid' -or $newSignature.SignerCertificate.Thumbprint.ToUpperInvariant() -notin $approvedSigners) {
                                throw 'Update is not validly signed by an approved certificate.'
                            }
                        }
                    } elseif ($extension -eq '.bat' -and $content -notmatch '(?im)^@?echo\s+off\s*$') {
                        throw 'Download is not a recognized batch launcher.'
                    }
                    if ($extension -eq '.bat') {
                        # BAT has no Authenticode support. Its approved hash is
                        # carried by the signed PowerShell script that launches it.
                        if (-not $ExpectedSha256 -or (Get-FileHash -LiteralPath $temporary -Algorithm SHA256 -ErrorAction Stop).Hash -ne $ExpectedSha256) {
                            throw 'Batch update does not match the hash approved by its PowerShell companion.'
                        }
                    }
                    $changed = (Get-FileHash -LiteralPath $temporary -Algorithm SHA256 -ErrorAction Stop).Hash -ne (Get-FileHash -LiteralPath $LocalPath -Algorithm SHA256 -ErrorAction Stop).Hash
                    if (-not $PSCmdlet.ShouldProcess($LocalPath, 'Install approved remote update and record version')) { break }
                    if ($changed) {
                        if ($extension -eq '.bat' -and $env:SCRIPT_LIBRARY_ACTIVE_LAUNCHER -eq $LocalPath) {
                            # CMD may still be reading this launcher. Its preamble applies this on next launch.
                            if (-not $content.Contains('SCRIPT_LIBRARY_ACTIVE_LAUNCHER')) { throw 'Batch update lacks the safe-update preamble.' }
                            $pending = $LocalPath + '.update.pending'
                            if (Test-Path -LiteralPath $pending) {
                                $pendingPrevious=$pending+'.'+[guid]::NewGuid().ToString('N')+'.previous'
                                [IO.File]::Replace($temporary, $pending, $pendingPrevious)
                            }
                            else { [IO.File]::Move($temporary, $pending) }
                        } else {
                            # Same-volume replacement is atomic. Keep the previous working copy.
                            [IO.File]::Replace($temporary, $LocalPath, ($LocalPath + '.bak'))
                        }
                        $temporary = $null
                        Write-Host "Updated $RepositoryPath from $($candidate.Name). The new version takes effect on the next run."
                    }
                    $stateTemporary = $statePath + '.' + [guid]::NewGuid().ToString('N') + '.tmp'
                    @{ CommittedAt = $candidate.Date.ToString('o'); Commit = $candidate.Sha; Source = $candidate.Name } |
                        ConvertTo-Json | Set-Content -LiteralPath $stateTemporary -Encoding UTF8 -ErrorAction Stop
                    if (Test-Path -LiteralPath $statePath) {
                        $statePrevious=$statePath+'.'+[guid]::NewGuid().ToString('N')+'.previous'
                        [IO.File]::Replace($stateTemporary, $statePath, $statePrevious)
                    }
                    else { [IO.File]::Move($stateTemporary, $statePath) }
                    $stateTemporary = $null
                    break
                } catch {
                    # Do not fall back after replacement if only recording state failed.
                    Write-Warning "Update could not complete for ${RepositoryPath}: $($_.Exception.Message)"
                    if (-not $temporary) { break }
                } finally {
                    if ($temporary -and (Test-Path -LiteralPath $temporary)) { Remove-Item -LiteralPath $temporary -Force -ErrorAction SilentlyContinue }
                    $temporary = $null
                }
            }
        } catch {
            Write-Warning "Update skipped for ${RepositoryPath}: $($_.Exception.Message)"
        } finally {
            if ($stateTemporary -and (Test-Path -LiteralPath $stateTemporary)) { Remove-Item -LiteralPath $stateTemporary -Force -ErrorAction SilentlyContinue }
            foreach ($previous in @($statePrevious,$pendingPrevious)) {
                if ($previous -and (Test-Path -LiteralPath $previous)) { Remove-Item -LiteralPath $previous -Force -ErrorAction SilentlyContinue }
            }
        }
    }
    Update-LibraryScript -LocalPath $PSCommandPath -RepositoryPath 'Intune Sync Fix/grsremediation.ps1' -Baseline '2026-11-06T00:00:00Z'
}
# END SCRIPT LIBRARY REMOTE UPDATE

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

#### BEGIN FUNCTIONS ####

<#
    .SYNOPSIS
    Retrieves the failed Win32 app states from the Intune registry.
    
    .DESCRIPTION
    This function searches the Intune Win32 apps registry key for subkeys containing an EnforcementStateMessage property.
    It extracts the error codes from these properties and identifies failed installations.

    .OUTPUTS
    PSCustomObject representing the failed app states.
#>
function Get-FailedWin32AppState {
    $win32AppsKeyPath = 'HKLM:\SOFTWARE\Microsoft\IntuneManagementExtension\Win32Apps'
    $appSubKeys = Get-ChildItem -Path $win32AppsKeyPath -Recurse -ErrorAction SilentlyContinue

    $failedStates = @()
    foreach ($subKey in $appSubKeys) {
        $enforcementStateMessage = Get-ItemProperty -Path $subKey.PSPath -Name EnforcementStateMessage -ErrorAction SilentlyContinue
        if ($enforcementStateMessage) {
            if ($enforcementStateMessage.EnforcementStateMessage -match '"ErrorCode":(-?\d+|null)') {
                $errorCodeRaw = $matches[1]
                if ($errorCodeRaw -ne "null") {
                    # Intune's EnforcementStateMessage sometimes serializes
                    # HRESULT-style codes as large unsigned decimals (e.g.
                    # 2147942402 for 0x80070102) that overflow Int32. A hard
                    # [int] cast used to throw on those, aborting this whole
                    # function (and every other app's remediation this run)
                    # instead of just skipping the one unparseable entry.
                    $errorCode = 0
                    if (-not [int]::TryParse($errorCodeRaw, [ref]$errorCode)) {
                        Write-Warning "Skipping unparseable/oversized ErrorCode '$errorCodeRaw' at $($subKey.PSPath)"
                        continue
                    }
                    if (($errorCode -ne 0) -and ($errorCode -ne 3010)) {
                        $failedStates += [PSCustomObject]@{
                            SubKeyPath = $subKey.PSPath
                            ErrorCode  = $errorCode
                        }
                    }
                }
            }
        }
    }

    return $failedStates
}


<#
    .SYNOPSIS
    Retrieves the last hash value for a specific user and app ID.
    
    .DESCRIPTION
    This function gets the LastHashValue property from the registry for a given user and app ID.

    .PARAMETER userObjectId
    The object ID of the user.

    .PARAMETER appId
    The ID of the app.

    .OUTPUTS
    The last hash value as a string.
#>
function Get-LastHashValue {
    param (
        [string]$userObjectId,
        [string]$appId
    )

    $reportingKeyPath = "HKLM:\SOFTWARE\Microsoft\IntuneManagementExtension\Win32Apps\Reporting\$userObjectId\$appId\ReportCache\$userObjectId"
    if (Test-Path -Path $reportingKeyPath) {
        $reportingKey = Get-ItemProperty -Path $reportingKeyPath -Name LastHashValue -ErrorAction SilentlyContinue
        return $reportingKey.LastHashValue
    }

    return $null
}

<#
    .SYNOPSIS
    Removes the registry keys for a failed app installation.
    
    .DESCRIPTION
    This function removes the registry keys associated with a failed app installation to trigger a reinstallation attempt.

    .PARAMETER userObjectId
    The object ID of the user.

    .PARAMETER appId
    The ID of the app.

    .PARAMETER lastHashValue
    The last hash value for the app.
#>
function Remove-FailedAppRegistryKey {
    # ConfirmImpact 'Medium' is below the default $ConfirmPreference of 'High',
    # so ShouldProcess never prompts here - this remediation runs unattended
    # under Intune - while -WhatIf still works for testing.
    [CmdletBinding(SupportsShouldProcess, ConfirmImpact = 'Medium')]
    param (
        [string]$userObjectId,
        [string]$appId,
        [string]$lastHashValue
    )

    $pathsToRemove = @(
        "HKLM:\SOFTWARE\Microsoft\IntuneManagementExtension\Win32Apps\$userObjectId\$appId", # App status per user
        "HKLM:\SOFTWARE\Microsoft\IntuneManagementExtension\Win32Apps\Reporting\$userObjectId\$appId", # Reporting key
        "HKLM:\SOFTWARE\Microsoft\IntuneManagementExtension\Win32Apps\$userObjectId\GRS\$lastHashValue" # GRS using last hash value
    )

    foreach ($path in $pathsToRemove) {
        if (Test-Path -Path $path) {
            if ($PSCmdlet.ShouldProcess($path, 'Remove registry key')) {
                Remove-Item -Path $path -Recurse -Force
                Write-Host "Removed registry key: $path"
            }
        }
        else {
            Write-Host "Registry key not found: $path"
        }
    }
}

<#
    .SYNOPSIS
    Retrieves the username from an object ID.
    
    .DESCRIPTION
    This function maps a user object ID to a username by searching the registry.

    .PARAMETER ObjectID
    The object ID of the user.

    .OUTPUTS
    The username as a string.
#>
function Get-UsernameFromObjectID {
    param (
        [string]$ObjectID
    )

    $userSIDs = Get-ChildItem -Path 'Registry::HKEY_USERS\'

    foreach ($userSID in $userSIDs) {
        $identityKeyPath = "Registry::HKEY_USERS\$($userSID.PSChildName)\Software\Microsoft\Office\16.0\Common\Identity"
        if (Test-Path -Path $identityKeyPath) {
            $identityKey = Get-ItemProperty -Path $identityKeyPath
            if ($identityKey.ConnectedAccountWamAad -eq $ObjectID) {
                return $identityKey.ADUserName
            }
        }
    }

    return $null
}

<#
    .SYNOPSIS
    Retrieves the error description for a given error code.
    
    .DESCRIPTION
    This function maps an error code to a descriptive message.

    .PARAMETER errorCode
    The error code as an integer.

    .OUTPUTS
    The error description as a string.
#>
# Loaded once at script scope instead of rebuilding a 60+ entry hashtable
# literal on every single Get-ErrorDescription call. The full table lives
# in MsiErrorCodes.json beside this script so it can be extended without
# touching the script itself; a small embedded fallback covers the most
# common codes if that file is ever missing (e.g. someone copied just the
# .ps1), so error lookups degrade instead of going fully blank.
$script:MsiErrorCodes = $null
function Get-MsiErrorCodeTable {
    if ($null -ne $script:MsiErrorCodes) { return $script:MsiErrorCodes }

    $jsonPath = Join-Path $PSScriptRoot 'MsiErrorCodes.json'
    if (Test-Path -LiteralPath $jsonPath) {
        try {
            $loaded = Get-Content -LiteralPath $jsonPath -Raw | ConvertFrom-Json
            $table = @{}
            foreach ($prop in $loaded.PSObject.Properties) { $table[$prop.Name] = $prop.Value }
            $script:MsiErrorCodes = $table
            return $script:MsiErrorCodes
        } catch {
            Write-Warning "Could not parse ${jsonPath}: $($_.Exception.Message). Falling back to a minimal built-in error code table."
        }
    }

    $script:MsiErrorCodes = @{
        '0x00000000' = "The action completed successfully."
        '0x80070642' = "The user canceled installation."
        '0x80070643' = "A fatal error occurred during installation."
        '0x80070652' = "Another installation is already in progress. Complete that installation before proceeding with this install."
        '0x80070666' = "Another version of this product is already installed. Installation of this version can't continue."
        '0x80070BB8' = "A restart is required to complete the install. This message indicates success."
    }
    return $script:MsiErrorCodes
}

function Get-ErrorDescription {
    param (
        [int]$errorCode
    )

    $errorCodes = Get-MsiErrorCodeTable
    $hexCode = [convert]::ToString($errorCode, 16).ToUpper()
    $hexCode = '0x' + $hexCode.PadLeft(8, '0')

    if ($errorCodes.ContainsKey($hexCode)) {
        return $errorCodes[$hexCode]
    }
    else {
        return "Unknown error code."
    }
}

#### SCRIPT ENTRY POINT ####

#Requires -RunAsAdministrator

$principal = [Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()
if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Write-Error 'This script must be run as Administrator.'
    exit 1
}

# Start Logging
$logDir = "C:\Windows\Logs"
$timestamp = Get-Date -Format "yyyyMMdd_HHmmss"
$logPath = Join-Path $logDir "App_Failure_Remediation_$timestamp.log"

# This transcript logs AD usernames next to failing AppIDs and was previously
# left to accumulate forever with the directory's default (broadly readable)
# ACL. Purge anything older than 30 days before adding to the pile, then
# lock the new file down below once it exists.
try {
    Get-ChildItem -Path $logDir -Filter 'App_Failure_Remediation_*.log' -ErrorAction SilentlyContinue |
        Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-30) } |
        Remove-Item -Force -ErrorAction SilentlyContinue
} catch {
    Write-Warning "Could not clean up old remediation logs in '$logDir': $($_.Exception.Message)"
}

Start-Transcript $logPath

try {
    icacls $logPath /inheritance:r /grant:r '*S-1-5-32-544:F' 'SYSTEM:F' | Out-Null
} catch {
    Write-Warning "Could not lock down ACL on log file '$logPath': $($_.Exception.Message)"
}

try {
    # Get the failed Win32 app states
    $failedStates = Get-FailedWin32AppState

    # Process each failed state
    foreach ($state in $failedStates) {
        try {
            # Parse the subkey path to extract User and App ID
            # Expected structure: ...\Win32Apps\<userObjId>\<appId>\... -
            # locate the Win32Apps segment and take the two after it, rather
            # than a hardcoded index. $state.SubKeyPath is $subKey.PSPath from
            # Get-FailedWin32AppState, a provider-qualified path (e.g.
            # "Microsoft.PowerShell.Core\Registry::HKEY_LOCAL_MACHINE\...") -
            # a previous `-replace 'HKLM:\\', ''` here never actually matched
            # that format and was a silent no-op; the fixed-index [6]/[7]
            # lookup below only happened to land correctly by coincidence of
            # the untouched prefix's segment count.
            $splitPath = $state.SubKeyPath -split '\\'
            $win32AppsIdx = [array]::IndexOf($splitPath, 'Win32Apps')

            if ($win32AppsIdx -lt 0 -or $splitPath.Count -lt ($win32AppsIdx + 3)) {
                Write-Warning "Unexpected registry path structure (Win32Apps segment not found or not followed by userObjectId/appId): $($state.SubKeyPath)"
                continue
            }

            $userObjectId = $splitPath[$win32AppsIdx + 1]
            $appId        = $splitPath[$win32AppsIdx + 2]

            if ([string]::IsNullOrWhiteSpace($userObjectId) -or [string]::IsNullOrWhiteSpace($appId)) {
                Write-Warning "Could not extract userObjectId or appId from path: $subKeyPath"
                continue
            }

            # Get the username
            $userName = Get-UsernameFromObjectID -ObjectID $userObjectId

            # Get the error description
            $errorDescription = Get-ErrorDescription -errorCode $state.ErrorCode

            Write-Host "AppID: $appId failed for user $userName - error $($state.ErrorCode): $errorDescription"

            # Get the LastHashValue and remove registry keys to force re-evaluation
            $lastHashValue = Get-LastHashValue -userObjectId $userObjectId -appId $appId

            if ($lastHashValue) {
                Remove-FailedAppRegistryKey -userObjectId $userObjectId -appId $appId -lastHashValue $lastHashValue
            } else {
                Remove-FailedAppRegistryKey -userObjectId $userObjectId -appId $appId
            }
        } catch {
            Write-Warning "Error processing state for $($state.SubKeyPath): $($_.Exception.Message)"
        }
    }

    # Restart the Intune Management Extension if any failures were remediated
    if ($failedStates.Count -gt 0) {
        Write-Host "Remediated $($failedStates.Count) failure(s). Restarting IntuneManagementExtension..."
        Restart-Service -Name 'IntuneManagementExtension' -Force -PassThru
    } else {
        Write-Host "No failures detected."
    }
    exit 0
} catch {
    Write-Error "Unhandled error in remediation script: $($_.Exception.Message)"
    exit 1
} finally {
    Stop-Transcript
}

